 const attachCallMedia=(stream:MediaStream)=>{localStreamRef.current=stream;cameraTrackRef.current=stream.getVideoTracks()[0]||null;micTrackRef.current=stream.getAudioTracks()[0]||null;setCameraEnabled(Boolean(cameraTrackRef.current?.enabled));setMicEnabled(Boolean(micTrackRef.current?.enabled));setLocalStream(stream)}

 const startCall=async(peer:User)=>{if(callPeerRef.current){show('Finish your current call before starting another.');return}if(!socketRef.current?.connected){show('Social Land is reconnecting. Try the call again in a moment.');return}try{iceQueue.current=[];const stream=await requestCallMedia();attachCallMedia(stream);setCallPeer(peer.id);callPeerRef.current=peer.id;setCallState('calling');const pc=makePeer(peer.id);stream.getTracks().forEach(track=>pc.addTrack(track,stream));const offer=await pc.createOffer();await pc.setLocalDescription(offer);socketRef.current?.emit('call:signal',{to:peer.id,kind:'offer',data:offer})}catch(e){endCall(false);show(e instanceof Error?e.message:'Camera or microphone permission was denied.')}}

