 const createGameVoicePeer=(peerId:string,initiator:boolean)=>{if(gameVoicePeers.current.has(peerId)||!gameVoiceSessionId.current)return;const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});const peer:GameVoicePeer={connection:pc,pending:[]};gameVoicePeers.current.set(peerId,peer);gameVoiceStream.current?.getTracks().forEach(track=>pc.addTrack(track,gameVoiceStream.current!));pc.onicecandidate=event=>{if(event.candidate)socketRef.current?.emit('game:voice:signal',{sessionId:gameVoiceSessionId.current,to:peerId,kind:'ice',data:event.candidate})};pc.ontrack=event=>{if(event.streams[0])setGameVoiceStreams(items=>({...items,[peerId]:event.streams[0]}))};if(initiator)void pc.createOffer().then(offer=>pc.setLocalDescription(offer).then(()=>socketRef.current?.emit('game:voice:signal',{sessionId:gameVoiceSessionId.current,to:peerId,kind:'offer',data:offer}))).catch(()=>show('Could not connect voice chat.'))};gameVoiceCreatePeerRef.current=createGameVoicePeer;gameVoiceHandleSignalRef.current=payload=>{if(payload.sessionId!==gameVoiceSessionId.current)return;void(async()=>{try{let peer=gameVoicePeers.current.get(payload.from);if(payload.kind==='offer'&&!peer){createGameVoicePeer(payload.from,false);peer=gameVoicePeers.current.get(payload.from)}if(!peer)return;const pc=peer.connection;if(payload.kind==='offer'){await pc.setRemoteDescription(payload.data);for(const c of peer.pending.splice(0))await pc.addIceCandidate(c);const answer=await pc.createAnswer();await pc.setLocalDescription(answer);socketRef.current?.emit('game:voice:signal',{sessionId:payload.sessionId,to:payload.from,kind:'answer',data:answer})}else if(payload.kind==='answer'){await pc.setRemoteDescription(payload.data);for(const c of peer.pending.splice(0))await pc.addIceCandidate(c)}else if(payload.kind==='ice'){if(pc.remoteDescription)await pc.addIceCandidate(payload.data);else peer.pending.push(payload.data)}}catch{show('Voice connection failed.')}})()};const cleanupGameVoice=(notify=true)=>{if(notify&&gameVoiceSessionId.current)socketRef.current?.emit('game:voice:leave',{sessionId:gameVoiceSessionId.current});gameVoicePeers.current.forEach(p=>p.connection.close());gameVoicePeers.current.clear();gameVoiceStream.current?.getTracks().forEach(t=>t.stop());gameVoiceStream.current=null;gameVoiceSessionId.current='';setGameVoiceStreams({});setGameVoiceMembers([]);setGameVoiceState('off');setGameVoiceMuted(false)};gameVoiceCleanupRef.current=cleanupGameVoice;const toggleGameVoice=async()=>{if(gameVoiceState!=='off'){cleanupGameVoice(true);return}try{setGameVoiceState('connecting');gameVoiceSessionId.current=gameSession?.id||'';gameVoiceStream.current=await navigator.mediaDevices.getUserMedia({audio:true});socketRef.current?.emit('game:voice:join',{sessionId:gameVoiceSessionId.current});setGameVoiceState('on')}catch(error){cleanupGameVoice(false);show(error instanceof Error?error.message:'Allow microphone access for voice chat.')}};const toggleGameVoiceMute=()=>{const muted=!gameVoiceMuted;gameVoiceStream.current?.getAudioTracks().forEach(track=>track.enabled=!muted);setGameVoiceMuted(muted)};const toggleGameFullscreen=async()=>{const target=gameSessionCardRef.current;if(!target)return;try{if(document.fullscreenElement)await document.exitFullscreen();else await target.requestFullscreen()}catch{show('Fullscreen is unavailable in this browser.')}};const sendGameChat=(event:FormEvent)=>{event.preventDefault();const text=gameChatDraft.trim();if(text&&gameSession)socketRef.current?.emit('game:chat:send',{sessionId:gameSession.id,text});setGameChatDraft('')}; const endCall=(signal=true)=>{if(signal&&callPeerRef.current)socketRef.current?.emit('call:signal',{to:callPeerRef.current,kind:'end'});screenStreamRef.current?.getTracks().forEach(track=>{track.onended=null;track.stop()});screenStreamRef.current=null;pcRef.current?.close();pcRef.current=null;localStreamRef.current?.getTracks().forEach(track=>track.stop());localStreamRef.current=null;cameraTrackRef.current=null;micTrackRef.current=null;iceQueue.current=[];pendingOffer.current=null;callPeerRef.current='';setLocalStream(null);setRemoteStream(null);setMicEnabled(true);setCameraEnabled(true);setSharingScreen(false);setCallState('idle');setCallPeer('');setCallMinimized(false)}; const logout=()=>{if(locationWatchRef.current!==null&&locationConversationRef.current)socketRef.current?.emit('location:stop',{conversationId:locationConversationRef.current});if(locationWatchRef.current!==null)navigator.geolocation.clearWatch(locationWatchRef.current);if(locationShareTimerRef.current)window.clearTimeout(locationShareTimerRef.current);locationWatchRef.current=null;liveCleanupRef.current(true);endCall(false);socketRef.current?.disconnect();localStorage.removeItem('looply-token');setToken('');setMe(null);setChats([]);setFriends([]);setMessages([]);setActiveChat(null);setChatViewOpen(false);setTab('Home')}

