 const createPost=async(e:FormEvent)=>{e.preventDefault();if(publishing)return;if(postKind==='post'&&!postFiles.length){show('Add at least one photo or video to publish a post. For text only, share a Note.');return}if(postKind==='reel'&&(postFiles.length!==1||!postFiles[0].type.startsWith('video/'))){show('Choose one video to publish a Reel.');return}if(postKind==='note'&&(!postCaption.trim()||postFiles.length)){show('Notes are text-only and need some text.');return}if(postFiles.length>10||postFiles.reduce((total,file)=>total+file.size,0)>200*1024*1024){show('A post can contain up to 10 media files and 200 MB total.');return}const form=new FormData();form.append('caption',postCaption);form.append('kind',postKind);postFiles.forEach(file=>form.append('media',file));setPublishing(true);try{const created=await apiForm<{post:SocialPost}>('/posts',token,form);setPostCaption('');setPostFiles([]);setComposerMediaIndex(0);if(postKind==='note')setProfileNotes(items=>[{id:created.post.id,authorId:me.id,text:created.post.caption,createdAt:created.post.createdAt,legacy:false},...items]);else await loadSocialPosts(postKind);show(postKind==='reel'?'Your Reel is live!':postKind==='note'?'Your note is live!':'Your post is live!')}catch(e){show((e as Error).message)}finally{setPublishing(false)}}

