 {tab==='Play'&&<section className="real-content"><RealHeading kicker="PLAY WITH FRIENDS" title="Game room." sub="Invite friends in chat, wait for them to accept, then start when everyone is ready."/><div className="game-hub"><div className="game-invite-setup"><label>CHOOSE A GAME<select value={gameChoice} onChange={event=>{setGameChoice(event.target.value as GameKind);setGameInviteFriends([])}}><option value="chess">Chess (2 players)</option><option value="ludo">Ludo (up to 4 players)</option><option value="tic-tac-toe">Tic Tac Toe (2 players)</option></select></label><div className="game-friend-picker"><b>Invite friends in chat <small>Choose up to {(gameChoice==='ludo'?4:2)-1} friend{gameChoice==='ludo'?'s':''}</small></b>{friends.length?friends.map(friend=><label key={friend.id}><input type="checkbox" checked={gameInviteFriends.includes(friend.id)} disabled={!gameInviteFriends.includes(friend.id)&&gameInviteFriends.length>=(gameChoice==='ludo'?3:1)} onChange={event=>setGameInviteFriends(ids=>event.target.checked?[...ids,friend.id]:ids.filter(id=>id!==friend.id))}/><Avatar user={friend}/><span>{friend.displayName}</span></label>):<small>Become friends with someone to invite them to games.</small>}</div><button className="real-button" disabled={!gameInviteFriends.length} onClick={()=>{socketRef.current?.emit('game:invite',{game:gameChoice,userIds:gameInviteFriends});setGameInviteFriends([]);show('Game invitations sent in chat.')}}><Gamepad2 size={15}/> Send game invite</button></div>{gameSession&&<div className="game-session-card" ref={gameSessionCardRef}><header><div><small>{gameSession.game==='chess'?'CHESS':gameSession.game==='ludo'?'LUDO':'TIC TAC TOE'} | {gameSession.status==='open'?'WAITING FOR PLAYERS':gameSession.status.toUpperCase()}</small><b>{gameSession.playerIds.length} / {gameSession.maxPlayers} players</b></div>{gameSession.hostId===me.id&&gameSession.status!=='ended'&&<button className="real-button outline" onClick={()=>socketRef.current?.emit('game:end',{sessionId:gameSession.id})}>End game</button>}</header><div className="game-player-list">{Array.from({length:gameSession.maxPlayers},(_,index)=>{const playerId=gameSession.playerIds[index];const invitedId=playerId?null:gameSession.invitedIds.filter(id=>!gameSession.playerIds.includes(id))[index-gameSession.playerIds.length];const userId=playerId||invitedId;const playerName=!userId?'Open seat':userId===me.id?'You':userId===gameSession.hostId?gameSession.hostName:friends.find(friend=>friend.id===userId)?.displayName||'Friend';return <span key={userId||`seat-${index}`} className={playerId?'arrived':userId?'invite-pending':'seat-open'}><i className="game-player-presence"/><b>{playerName}</b><small>{playerId?(index===0&&gameSession.game==='chess'?'White':index===1&&gameSession.game==='chess'?'Black':'Joined') :userId?'Invite sent · waiting':'Available seat'}</small></span>})}</div>{gameSession.status==='open'?<div className="game-waiting"><span>Invite sent. Players can accept from their chat with you.</span>{gameSession.hostId===me.id&&<button className="real-button" disabled={gameSession.playerIds.length<2} onClick={()=>socketRef.current?.emit('game:start',{sessionId:gameSession.id})}>Start game</button>}</div>:gameSession.status==='ended'?<p className="game-closed">This game has ended. New players cannot join.</p>:<Suspense fallback={<GameAssetLoader game={gameSession.game} progress={gameLoadProgress}/> }><div className="game-active-board"><ThreeGameScene game={gameSession.game} session={gameSession} userId={me.id} names={gameSession.playerIds.map(id=>id===me.id?'You':id===gameSession.hostId?gameSession.hostName:friends.find(friend=>friend.id===id)?.displayName||'Friend')} selected={chessSelection} onSelect={setChessSelection} onMove={(from,to)=>{socketRef.current?.emit('game:action',{sessionId:gameSession.id,action:{type:'move',from,to}});setChessSelection(null)}} onPieceMove={piece=>socketRef.current?.emit('game:action',{sessionId:gameSession.id,action:{type:'move',piece}})} onPlace={index=>socketRef.current?.emit('game:action',{sessionId:gameSession.id,action:{type:'place',index}})} onRoll={()=>socketRef.current?.emit('game:action',{sessionId:gameSession.id,action:{type:'roll'}})} onReady={()=>{gameSceneReady.current=true;setGameLoadProgress(100)}}/></div><GameLiveControls voiceState={gameVoiceState} voiceMuted={gameVoiceMuted} voiceCount={gameVoiceMembers.length+1} chatOpen={gameChatOpen} isFullscreen={gameIsFullscreen} onFullscreen={()=>void toggleGameFullscreen()} onVoice={()=>void toggleGameVoice()} onMute={toggleGameVoiceMute} onChat={()=>setGameChatOpen(open=>!open)} onResign={()=>{if(window.confirm('Resign this game? The other players will win.'))socketRef.current?.emit('game:resign',{sessionId:gameSession.id})}} onExit={()=>{gameVoiceCleanupRef.current(true);socketRef.current?.emit('game:leave',{sessionId:gameSession.id});setGameSession(null)}}/>{gameChatOpen&&<GameTextChat messages={gameChatMessages} userId={me.id} draft={gameChatDraft} onDraft={setGameChatDraft} onSend={sendGameChat}/>}<div className="game-voice-audio" aria-hidden="true">{Object.entries(gameVoiceStreams).map(([userId,stream])=><audio key={userId} autoPlay ref={element=>{if(element&&element.srcObject!==stream)element.srcObject=stream}}/>)}</div></Suspense>}</div>}</div></section>}

