function PartyInviteCard({invite,currentUserId,onJoin}:{invite:PartyInvite;currentUserId:string;onJoin:()=>void}){const invited=invite.invitedIds.includes(currentUserId);const joined=invite.participantIds.includes(currentUserId);return <div className="chat-game-invite party-chat-invite"><b><Video size={15}/> Watch room invitation</b><small>{invite.hostName} invited friends · {invite.participantIds.length} watching</small>{invite.status==='open'&&invited&&<button type="button" onClick={onJoin}>{joined?'Open watch room':'Join watch room'}</button>}{invite.status==='ended'&&<small>This room has ended.</small>}</div>}
function GameInviteCard({invite,currentUserId,onAccept,onDecline,onJoin}:{invite:GameInvite;currentUserId:string;onAccept:()=>void;onDecline:()=>void;onJoin:()=>void}){const invited=invite.invitedIds.includes(currentUserId);const joined=invite.playerIds.includes(currentUserId);const title=invite.game==='tic-tac-toe'?'Tic Tac Toe':invite.game==='chess'?'Chess':'Ludo';return <div className="chat-game-invite"><b><Gamepad2 size={15}/> {title} invitation</b><small>{invite.hostName} invited friends. {invite.playerIds.length}/{invite.maxPlayers} joined</small>{invite.status==='open'&&invited&&!joined&&<span><button type="button" onClick={onAccept}>Accept</button><button type="button" onClick={onDecline}>Decline</button></span>}{invite.status==='open'&&joined&&<small>Accepted. Waiting for host to start</small>}{invite.status==='open'&&invited&&!joined&&invite.playerIds.length>=invite.maxPlayers&&<small>Game is full. Join closed</small>}{invite.status==='open'&&!invited&&<small>This invitation is no longer active</small>}{invite.status==='started'&&joined&&<button type="button" onClick={onJoin}>Join game</button>}{invite.status==='started'&&!joined&&<small>Game started. Join closed</small>}{invite.status==='ended'&&<small>Game ended. Join closed</small>}</div>}
