function GameTextChat({messages,userId,draft,onDraft,onSend}:{messages:GameChatLine[];userId:string;draft:string;onDraft:(value:string)=>void;onSend:(event:FormEvent)=>void}){return <aside className="game-text-chat"><header>Game chat <small>Players only</small></header><div className="game-chat-log">{messages.map(message=><p key={message.id} className={message.userId===userId?'mine':''}><b>{message.displayName}</b><span>{message.text}</span></p>)}</div><form onSubmit={onSend}><input value={draft} maxLength={500} onChange={event=>onDraft(event.target.value)} placeholder="Message players..."/><button type="submit" disabled={!draft.trim()}>Send</button></form></aside>}function RealHeading({kicker,title,sub,action}:{kicker:string;title:string;sub:string;action?:ReactNode}){return <div className="real-heading"><div><small>{kicker}</small><h1>{title}</h1><p>{sub}</p></div>{action}</div>}

function UserCard({user,onRequest,onAccept,onChat,onCall,hasStory,storySeen,onOpenStory,onOpenProfile,onFollow,onApproveFollow,onRejectFollow}:{user:User;onRequest?:()=>void;onFollow?:()=>void;onApproveFollow?:()=>void;onRejectFollow?:()=>void;onAccept?:()=>void;onChat?:()=>void;onCall?:()=>void;hasStory?:boolean;storySeen?:boolean;onOpenStory?:()=>void;onOpenProfile?:(username:string)=>void}){return <article className="user-card"><Avatar user={user} hasStory={hasStory} seenStory={storySeen} onClick={onOpenStory}/><span className="user-card-copy"><b><button type="button" className="profile-link" onClick={()=>onOpenProfile?.(user.username)}>{user.displayName}</button></b><small><button type="button" className="profile-link" onClick={()=>onOpenProfile?.(user.username)}>@{user.username}</button></small>{user.suggestionReason&&<small className="suggestion-reason">{user.suggestionReason}</small>}{user.bio&&<p>{user.bio}</p>}<ProfileDetails user={user} compact/></span><div className="user-card-actions">{onFollow&&<button type="button" className="real-button" onClick={onFollow}>{user.isFollowing?"Following":user.isFollowRequested?"Requested":"Follow"}</button>}{onApproveFollow&&<button type="button" className="real-button" onClick={onApproveFollow}><Check size={14}/> Approve follow</button>}{onRejectFollow&&<button type="button" className="real-button outline" onClick={onRejectFollow}>Decline</button>}{onRequest&&user.relationship!=='friend'&&<button className="real-button" disabled={user.relationship==='sent'} onClick={onRequest}>{user.relationship==='sent'?'Request sent':user.relationship==='received'?'Accept request':<><Plus size={14}/> Add friend</>}</button>}{onAccept&&<button className="real-button" onClick={onAccept}><Check size={14}/> Accept</button>}{onChat&&<button className="real-button outline" onClick={onChat}><MessageCircle size={15}/> Message</button>}{onCall&&<button className="real-button outline" onClick={onCall}><Video size={15}/> Call</button>}</div></article>}



function YouTubeEmbed({videoId,interactive,onReady,onStateChange,onError}:{videoId:string;interactive:boolean;onReady:(player:YouTubePlayer|null)=>void;onStateChange:(state:number)=>void;onError:(code:number|string)=>void}){

 const host=useRef<HTMLDivElement>(null);const callbacks=useRef({onReady,onStateChange,onError});callbacks.current={onReady,onStateChange,onError}

 useEffect(()=>{let cancelled=false;let player:YouTubePlayer|null=null;loadYouTubeApi().then(api=>{if(cancelled||!host.current)return;player=new api.Player(host.current,{width:'100%',height:'100%',videoId,playerVars:{playsinline:1,origin:window.location.origin,enablejsapi:1,controls:interactive?1:0},events:{onReady:(event:{target:YouTubePlayer})=>callbacks.current.onReady(event.target),onStateChange:(event:{data:number})=>callbacks.current.onStateChange(event.data),onError:(event:{data:number})=>callbacks.current.onError(event.data)}})}).catch(error=>callbacks.current.onError(error instanceof Error?error.message:'YouTube player could not load.'));return()=>{cancelled=true;player?.destroy();callbacks.current.onReady(null)}},[videoId])

 return <div className={"youtube-player-mount"+(interactive?"":" read-only")} ref={host}/>

}



function AuthScreen({onAuth}:{onAuth:(token:string,user:User)=>void}){

 const initialResetToken=new URLSearchParams(window.location.search).get('resetToken')||''

 const [mode,setMode]=useState<'login'|'register'|'forgot'|'reset'>(initialResetToken?'reset':'register')

 const [identity,setIdentity]=useState('');const [username,setUsername]=useState('');const [displayName,setDisplayName]=useState('');const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [confirmPassword,setConfirmPassword]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [success,setSuccess]=useState('')

 const submit=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError('');setSuccess('');try{

  if(mode==='forgot'){const d=await api<{development:boolean}>('/auth/forgot-password','',{method:'POST',body:JSON.stringify({email})});setSuccess(d.development?'If an account exists for that email, its reset link is in the development server terminal.':'If an account exists for that email, a password reset link will arrive shortly.');return}

  if(mode==='reset'){if(password!==confirmPassword)throw new Error('The new passwords do not match.');await api('/auth/reset-password','',{method:'POST',body:JSON.stringify({token:initialResetToken,password})});window.history.replaceState({},'',window.location.pathname);setMode('login');setPassword('');setConfirmPassword('');setSuccess('Your password has been reset. Log in with your new password.');return}

  const d=await api<{token:string;user:User}>('/auth/'+(mode==='register'?'register':'login'),'',{method:'POST',body:JSON.stringify(mode==='register'?{username,displayName,email,password}:{identity,password})});onAuth(d.token,d.user)

 }catch(e){setError((e as Error).message)}finally{setBusy(false)}}

 const heading=mode==='register'?'Find your people.':mode==='login'?'Welcome back.':mode==='forgot'?'Reset your password.':'Choose a new password.'

 const sub=mode==='register'?'Create your Social Land account and start building your circle.':mode==='login'?'Log in and pick up right where you left off.':mode==='forgot'?'Enter the email address linked to your account. We’ll send a secure reset link.':'Your reset link is private and expires after 30 minutes.'

 return <div className="auth-page"><div className="auth-side"><button className="brand" onClick={()=>location.reload()}><span className="brand-mark"><Sparkles size={19}/></span><span>Social Land</span></button><div className="auth-art"><div className="auth-art-orb">&#10022;</div><div className="auth-art-ball">&#9679;</div><span className="auth-art-message">Hey, you're here <b>&#9829;</b></span><i>&#10022;</i><span className="auth-art-sparkle">&#10023;</span></div><div className="auth-side-copy"><span>YOUR PEOPLE, CLOSE BY</span><h2>Good things<br/>happen <em>together.</em></h2><p>One cozy corner for conversations, games, and little moments with your people.</p><div className="auth-trust"><Check size={14}/> Make your circle yours</div></div><div className="auth-side-footer">Your people, together. <span>&#10022;</span></div></div><main className="auth-main"><div className="auth-mobile-brand"><span className="brand-mark"><Sparkles size={19}/></span>Social Land</div><div className="auth-form-wrap"><div className="auth-kicker">{mode==='register'?'COME ON IN':mode==='login'?'GOOD TO HAVE YOU BACK':'ACCOUNT SECURITY'}</div><h1>{heading}</h1><p className="auth-sub">{sub}</p>{error&&<div className="auth-error">{error}</div>}{success&&<div className="auth-success">{success}</div>}<form className="auth-form" onSubmit={submit}>

 {mode==='register'?<><label>YOUR NAME<input required value={displayName} onChange={e=>setDisplayName(e.target.value)} placeholder="What should we call you?" maxLength={50}/></label><label>CHOOSE A USERNAME<div className="username-field"><span>@</span><input required minLength={3} maxLength={24} pattern="[A-Za-z0-9_]+" value={username} onChange={e=>setUsername(e.target.value)} placeholder="yourname"/></div><small>Letters, numbers, and underscores. At least 3 characters.</small></label><label>EMAIL ADDRESS<input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" autoComplete="email"/></label></>:null}

 {mode==='login'&&<label>EMAIL OR USERNAME<input required value={identity} onChange={e=>setIdentity(e.target.value)} placeholder="you@example.com or username" autoComplete="username"/></label>}

 {mode==='forgot'&&<label>ACCOUNT EMAIL<input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" autoComplete="email"/></label>}

 {mode==='reset'?<><label>NEW PASSWORD<input type="password" required minLength={8} maxLength={72} value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 8 characters" autoComplete="new-password"/></label><label>CONFIRM NEW PASSWORD<input type="password" required minLength={8} maxLength={72} value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)} placeholder="Enter it one more time" autoComplete="new-password"/></label></>:mode!=='forgot'?<><label>PASSWORD<input type="password" required minLength={mode==='register'?8:1} maxLength={72} value={password} onChange={e=>setPassword(e.target.value)} placeholder={mode==='register'?'At least 8 characters':'Your password'} autoComplete={mode==='register'?'new-password':'current-password'}/>{mode==='register'&&<small>Use at least 8 characters.</small>}</label>{mode==='login'&&<button type="button" className="auth-forgot" onClick={()=>{setEmail(identity.includes('@')?identity:'');setMode('forgot');setError('');setSuccess('')}}>Forgot password?</button>}</>:null}

 <button className="auth-submit" disabled={busy}>{busy?'One moment…':mode==='register'?'Create my account':mode==='login'?'Log in':mode==='forgot'?'Send reset link':'Save new password'}<span>&#8594;</span></button></form>

 <div className="auth-switch">{mode==='register'?'Already have an account?':mode==='login'?'New to Social Land?':mode==='forgot'?'Remembered your password?':'Need a different account?'} <button onClick={()=>{setMode(mode==='register'?'login':'login');setError('');setSuccess('')}}>{mode==='register'?'Log in':mode==='login'?'Create an account':'Back to log in'}</button></div>

 {mode==='register'&&<><div className="auth-divider"><span>YOUR SPACE, YOUR PACE</span></div><div className="auth-benefits"><span><Check size={14}/> Your own Social Land ID</span><span><Check size={14}/> Private friend chats</span></div><small className="auth-terms">By continuing, you agree to be kind to one another.</small></>}</div><footer className="auth-mobile-footer">© Social Land | Your people, together</footer></main></div>

}





